args:
$json = [Console]::In.ReadToEnd() | ConvertFrom-Json
$f = $json.tool_input.file_path
if (-not $f) { $f = $json.tool_response.filePath }
if ($f -and $f.ToLower().EndsWith('.py') -and ($f -like 'C:\AI-SYSTEM\kesfetplus\*')) {
  $ruff = 'C:\AI-SYSTEM\kesfetplus\venv\Scripts\ruff.exe'
  if (Test-Path $ruff) {
    & $ruff check --fix $f 2>$null
    & $ruff format $f 2>$null
  }
}

$json = [Console]::In.ReadToEnd() | ConvertFrom-Json
$f = $json.tool_input.file_path
if ($f -and $f -like 'C:\AI-SYSTEM\kesfetplus\*') {
  $name = Split-Path $f -Leaf
  $lower = $name.ToLower()
  $safe = @('.env.example','.env.sample','.env.template','.env.dist')
  if (($lower -eq '.env' -or $lower -like '.env.*') -and ($safe -notcontains $lower)) {
    $reason = 'Guvenlik: ' + $name + ' bir .env dosyasi olabilir ve gizli anahtar icerebilir. PreToolUse hook yazmayi/duzenlemeyi engelledi.'
    $out = @{ hookSpecificOutput = @{ hookEventName = 'PreToolUse'; permissionDecision = 'deny'; permissionDecisionReason = $reason } }
    $out | ConvertTo-Json -Compress -Depth 5
    exit 2
  }
}
exit 0

$proj = 'C:\AI-SYSTEM\kesfetplus'
$lines = New-Object System.Collections.Generic.List[string]
try {
  $branch = & git -C $proj rev-parse --abbrev-ref HEAD 2>$null
  if ($branch) { $lines.Add('Git dal: ' + $branch) }
  $hash = & git -C $proj log -1 --pretty=format:%h 2>$null
  $subject = & git -C $proj log -1 --pretty=format:%s 2>$null
  $rel = & git -C $proj log -1 --pretty=format:%cr 2>$null
  if ($hash) { $lines.Add('Son commit: ' + $hash + ' - ' + $subject + ' (' + $rel + ')') }
  $status = & git -C $proj status --porcelain 2>$null
  if ($status) {
    $count = ($status | Where-Object { $_ -ne '' }).Count
    $lines.Add('Commit edilmemis degisiklik: ' + $count + ' dosya')
  }
} catch {}
$ports = @{ 8000 = 'FastAPI backend'; 5173 = 'Vite frontend'; 3000 = 'Frontend' }
foreach ($p in $ports.Keys) {
  $conn = Get-NetTCPConnection -LocalPort $p -State Listen -ErrorAction SilentlyContinue
  if ($conn) { $lines.Add('Port ' + $p + ' acik (' + $ports[$p] + ' calisiyor olabilir)') }
}
if ($lines.Count -eq 0) { $lines.Add('kesfetplus: git/port bilgisi alinamadi.') }
$ctx = [string]::Join([Environment]::NewLine, $lines)
$out = @{ hookSpecificOutput = @{ hookEventName = 'SessionStart'; additionalContext = $ctx } }
$out | ConvertTo-Json -Compress -Depth 5
